import math
import torch

EPS = 1e-12
R_C = 1.0  # FROZEN c = 1 ball radius, never recomputed


def _norm(v):
    return torch.sqrt(torch.clamp((v * v).sum(-1), min=0.0))


def _as_curvature(curvature):
    if isinstance(curvature, torch.Tensor):
        return float(curvature.detach().reshape(-1)[0].item())
    return float(curvature)


def lift(v, curvature=1.0):
    c = _as_curvature(curvature)
    if c == 0.0:
        return v
    s = math.sqrt(c)
    n = _norm(v)
    return v * (torch.tanh(s * n) / (s * n + EPS)).unsqueeze(-1)


def mobius(x, y, curvature=1.0):
    c = _as_curvature(curvature)
    xy = (x * y).sum(-1, keepdim=True)
    xn = (x * x).sum(-1, keepdim=True)
    yn = (y * y).sum(-1, keepdim=True)
    if c == 0.0:
        return x + y
    num = (1.0 + 2.0 * c * xy + c * yn) * x + (1.0 - c * xn) * y
    den = 1.0 + 2.0 * c * xy + c * c * xn * yn + EPS
    return num / den


def dist(x, y, curvature=1.0):
    c = _as_curvature(curvature)
    if c == 0.0:
        return 2.0 * _norm(x - y)
    s = math.sqrt(c)
    m = mobius(-x, y, c)
    return (2.0 / s) * torch.atanh(torch.clamp(s * _norm(m), max=1.0 - 1e-6))


def distance(x, y, curvature=1.0):
    x = x if isinstance(x, torch.Tensor) else torch.as_tensor(x, dtype=torch.float32)
    y = y if isinstance(y, torch.Tensor) else torch.as_tensor(y, dtype=torch.float32)
    if x.shape != y.shape:
        y = y.expand_as(x)
    return dist(x, y, curvature)

KEY POINTS the verifier must check: (1) the Mobius sum is applied to X = -x, so the num/den use +2c*<x,y> only because the listing's `xy` is already the negated inner product (numerically 1 - 2c<x,y> + c||y||^2 and 1 - 2c<x,y> + c^2||x||^2||y||^2); (2) the factor 2/sqrt(c) is present; (3) at c = 0 the value is exactly 2||x - y||; (4) the artanh argument is clamped only from above at 1 - 1e-6; (5) eps = 1e-12 sits in the mobius denominator (and in the lift denominator); (6) no lift is applied inside `distance` — `lift` is exported but the surface computes the statements on the raw arguments, as the specification's `statements` do.
